<?php declare(strict_types=1); namespace App\Domains\Patient\Policies; use App\Domains\User\Models\User; use App\Domains\Patient\Models\Patient;
final class PatientPolicy { public function viewAny(User $u): bool { return true; } public function view(User $u, Patient $p): bool { return $u->organization_id === $p->organization_id; } public function create(User $u): bool { return $u->hasRole(['Super Admin','Owner']); } public function update(User $u, Patient $p): bool { return $u->hasRole(['Super Admin','Owner']) && $u->organization_id === $p->organization_id; } public function delete(User $u, Patient $p): bool { return $u->hasRole(['Super Admin','Owner']) && $u->organization_id === $p->organization_id; } }
